use system.ops
use system.result
// Represents an environment variable operation error.
@non_exhaustive
public enum EnvError
    InvalidName(String)
    InvalidValue(String)
    Other(String)
// Environment variable capability class. Acquire a handle with `let env = Env()`.
public class Env
    // Returns the value of an environment variable, or None if it is not set.
    public fn get(name String) String?
    // Sets an environment variable for this process and its children.
    public fn set(name String, value String) Result<bool, EnvError>
// Command-line arguments passed to the program, excluding the program path.
public class Args implements Iterable<String>
    // Returns the number of arguments, excluding the program path.
    public fn length() int
    // Returns the argument at the given 0-based index.
    public fn element_at(index int) String
// Returns the name of the host platform, such as "macos", "linux" or "windows".
public fn platform() String
== system.process
// Terminates the program with the given exit code.
public fn exit(code int)
== system.text
use system.result
use system.string
use system.collections.list
// Represents a regex compilation or operation error.
@non_exhaustive
public enum RegexError
    SyntaxError(String)
    SizeExceeded(String)
    Other(String)
// A match result carrying the byte range and matched text.
public class Match
    fn init(start int, end int, text String)
    // Returns the start byte offset of the match (inclusive).
    public fn start() int
    // Returns the end byte offset of the match (exclusive).
    public fn end() int
    // Returns the matched text substring.
    public fn text() String
// A compiled regular expression pattern cached in the runtime slab.
public class Regex
    fn init(handle int)
    // Compiles a regex pattern into a reusable Regex object.
    public static fn compile(pattern String) Result<Regex, RegexError>
    // Constructs a Regex from a pattern the compiler has already validated.
    static fn from_validated_pattern(pattern String) Regex
    // Returns true if the pattern matches anywhere in the input string.
    public fn matches(text String) bool
    // Returns the first match of the pattern in the input string, or None.
    public fn find(text String) Match?
    // Returns a list of all non-overlapping matches of the pattern in the input string.
    public fn find_all(text String) [Match]
    // Replaces all non-overlapping matches with a literal replacement string.
    public fn replace(text String, to String) String
